let rows=JSON.parse(localStorage.getItem('qa-drawings')||'null')||[legacy];window.qaRows=()=>rows;
const client={from(table){let op='select',payload,id,ownerIds,ownerId,single=false;const q={select(){return q},eq(k,v){if(k==='id')id=v;if(k==='owner_id')ownerId=v;return q},in(k,v){if(k==='owner_id')ownerIds=v;return q},is(){return q},not(){return q},order(){return q},limit(){return q},single(){single=true;return q},insert(v){op='insert';payload=v;return q},update(v){op='update';payload=v;return q},delete(){op='delete';return q},then(resolve){let result=table==='profiles'?{username:'fixture',display_name:'Fixture'}:[];if(table==='user_products'&&params.has('paletteFailure'))return Promise.resolve({error:{message:'Palette unavailable'}}).then(resolve);if(table==='pro_creations'){let matches=rows.filter(row=>(!id||row.id===id)&&(!ownerId||row.owner_id===ownerId)&&(!ownerIds||ownerIds.includes(row.owner_id)));if(op==='insert'){result={...payload,id:messageId()};rows.unshift(result);}else if(op==='update'){result=matches[0];Object.assign(result,payload);}else result=single?matches[0]:matches;if(op!=='select')localStorage.setItem('qa-drawings',JSON.stringify(rows));}return Promise.resolve({data:structuredClone(result),count:0,...(single&&!result?{error:{message:'Missing'}}:{})}).then(resolve)}};return q},async rpc(){return {data:[]}}};
